onClick:
{{
  (async function() {
    // Si on est sur l'onglet Planning, on ouvre la modale des créneaux
    if (Tabs1.selectedTab === "📅 Planning") {
      await resetWidget('modal_add_creneau', true);
      showModal('modal_add_creneau');
    } 
    // Sinon, on est sur l'atelier, on ouvre la modale des interventions
    else {
      // 1. On vide la mémoire du client et de la machine
      await storeValue('nouveau_client_id', '');
      await storeValue('nouvelle_machine_id', '');

      // 2. On réinitialise les champs de la modale
      await resetWidget('modal_add_intervention', true);

      // 3. On charge la liste des clients en arrière-plan
      Get_Clients_Options.run();

      // 4. On ouvre la modale
      showModal('modal_add_intervention');
    }
  })()
}}
